import json,numpy as np
from PIL import Image
from scipy.ndimage import label
for a in ['initial','search_sugar']:
 m=json.load(open('/app/output/'+a+'/meta.json'))
 print('\n',a)
 for cam in ['robot0_agentview_left','robot0_agentview_center','robot0_agentview_right']:
  I=np.array(Image.open('/app/output/'+a+'/last/'+cam+'.jpg')).astype(float); D=np.load('/app/output/'+a+'/depth_'+cam+'.npy')[0].astype(float);K=np.array(m['cameras'][cam]['intrinsic_cv']);T=np.array(m['cameras'][cam]['cam2world_gl']);
  yy,xx=np.indices(D.shape);pc=np.stack([(xx-160)*D/K[0,0],-(yy-120)*D/K[1,1],-D,np.ones_like(D)],-1);W=pc@T.T;X,Y,Z=W[:,:,0],W[:,:,1],W[:,:,2]
  red=(I[:,:,0]>50)&(I[:,:,0]>I[:,:,1]*1.35)&(I[:,:,0]>I[:,:,2]*1.18)&(I[:,:,1]<110)&(I[:,:,2]<110)
  mask=red&(Z>.925)&(Z<.98)&(X>3.4)&(X<4.0)&(Y>-1.3)&(Y<-.5)
  lab,n=label(mask); L=[]
  for i in range(1,n+1):
   ids=np.where(lab==i);sz=len(ids[0]);
   if sz>=2:L.append((sz,(int(ids[1].min()),int(ids[0].min()),int(ids[1].max()),int(ids[0].max())),np.round(np.median(W[ids][:,:3],axis=0),3)))
  print(cam,sorted(L,key=lambda q:-q[0])[:20])
